-- OPS-LOG-OWNER-SESSION-1 (2026-11-05, charter pillar security; found while reading ops_ai_log for RM-POLICY-SMT-GATE-1): the owner_verify tool result, which carries the live owner session
-- token (qos_ followed by 64 hex characters, valid 12 hours), was written unmasked to ops_ai_log.tool_calls (22 rows since 2026-09-01) and ops_jobs (4 rows). redactSecrets in
-- qnfo-ops/worker.js masks neither: the hex rule needs a word boundary and the underscore of the prefix is a word character, the base64 rule needs an upper-case letter, and the
-- token-key rule does not list owner_session. This file removes the stored values (the code fix is the issue filed below). Each statement replaces the first token of a field, and the
-- marker holds no qos_ prefix, so three passes clear up to three distinct tokens per field. The 64-character check keeps a field that merely mentions the prefix untouched.
-- APPLY-BY: ci
-- DB: qnfo-audit
-- Rollback: none (a redaction of a credential is not reversed; the removed values were owner session tokens that expire 12 hours after minting)

UPDATE ops_ai_log SET tool_calls = replace(tool_calls, substr(tool_calls, instr(tool_calls, 'qos_'), 68), 'owner-session-[redacted]') WHERE ts > '2026-09-01' AND tool_calls LIKE '%qos\_%' ESCAPE '\' AND substr(tool_calls, instr(tool_calls, 'qos_') + 4, 64) NOT GLOB '*[^0-9a-f]*' AND length(substr(tool_calls, instr(tool_calls, 'qos_') + 4, 64)) = 64;
UPDATE ops_ai_log SET tool_calls = replace(tool_calls, substr(tool_calls, instr(tool_calls, 'qos_'), 68), 'owner-session-[redacted]') WHERE ts > '2026-09-01' AND tool_calls LIKE '%qos\_%' ESCAPE '\' AND substr(tool_calls, instr(tool_calls, 'qos_') + 4, 64) NOT GLOB '*[^0-9a-f]*' AND length(substr(tool_calls, instr(tool_calls, 'qos_') + 4, 64)) = 64;
