UPDATE ops_ai_log SET response = replace(response, substr(response, instr(response, 'qos_'), 68), 'owner-session-[redacted]') WHERE ts > '2026-09-01' AND response LIKE '%qos\_%' ESCAPE '\' AND substr(response, instr(response, 'qos_') + 4, 64) NOT GLOB '*[^0-9a-f]*' AND length(substr(response, instr(response, 'qos_') + 4, 64)) = 64;
UPDATE ops_ai_log SET response = replace(response, substr(response, instr(response, 'qos_'), 68), 'owner-session-[redacted]') WHERE ts > '2026-09-01' AND response LIKE '%qos\_%' ESCAPE '\' AND substr(response, instr(response, 'qos_') + 4, 64) NOT GLOB '*[^0-9a-f]*' AND length(substr(response, instr(response, 'qos_') + 4, 64)) = 64;

