UPDATE ops_ai_log SET prompt = replace(prompt, substr(prompt, instr(prompt, 'qos_'), 68), 'owner-session-[redacted]') WHERE ts > '2026-09-01' AND prompt LIKE '%qos\_%' ESCAPE '\' AND substr(prompt, instr(prompt, 'qos_') + 4, 64) NOT GLOB '*[^0-9a-f]*' AND length(substr(prompt, instr(prompt, 'qos_') + 4, 64)) = 64;

